B.a33=s(["\u0627\u0644\u0625\u0639\u0644\u0627\u0646\u0627\u062a (Google AdMob)","\u0627\u0644\u062a\u0637\u0628\u064a\u0642 \u0645\u062c\u0627\u0646\u064a \u0628\u0641\u0636\u0644 \u0625\u0639\u0644\u0627\u0646\u0627\u062a \u062a\u0642\u062f\u0651\u0645\u0647\u0627 Google AdMob. \u0644\u0639\u0631\u0636 \u0627\u0644\u0625\u0639\u0644\u0627\u0646\u0627\u062a \u0648\u0642\u064a\u0627\u0633\u0647\u0627 \u0648\u0645\u0646\u0639 \u0627\u0644\u0627\u062d\u062a\u064a\u0627\u0644\u060c \u0642\u062f \u062a\u062c\u0645\u0639 Google: \u0627\u0644\u0645\u0639\u0631\u0651\u0641 \u0627\u0644\u0625\u0639\u0644\u0627\u0646\u064a \u0644\u062c\u0647\u0627\u0632\u0643\u060c \u0648\u0639\u0646\u0648\u0627\u0646 IP (\u0645\u0648\u0642\u0639 \u062a\u0642\u0631\u064a\u0628\u064a)\u060c \u0648\u0645\u0639\u0644\u0648\u0645\u0627\u062a \u0627\u0644\u062c\u0647\u0627\u0632 \u0648\u0627\u0644\u0646\u0638\u0627\u0645\u060c \u0648\u062a\u0641\u0627\u0639\u0644\u0627\u062a\u0643 \u0645\u0639 \u0627\u0644\u0625\u0639\u0644\u0627\u0646\u0627\u062a. \u0648\u062a\u062a\u0635\u0631\u0641 Google \u0643\u0645\u0633\u0624\u0648\u0644 \u0645\u0633\u062a\u0642\u0644 \u0639\u0646 \u0647\u0630\u0647 \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a. \u0627\u0644\u062a\u0641\u0627\u0635\u064a\u0644: https://policies.google.com/technologies/partner-sites"],t.s)
B.U4=s(["\u0627\u0644\u0623\u0633\u0627\u0633 \u0627\u0644\u0642\u0627\u0646\u0648\u0646\u064a (GDPR)","\u0628\u0627\u0644\u0646\u0633\u0628\u0629 \u0644\u0644\u0645\u0633\u062a\u062e\u062f\u0645\u064a\u0646 \u0641\u064a \u0627\u0644\u0645\u0646\u0637\u0642\u0629 \u0627\u0644\u0627\u0642\u062a\u0635\u0627\u062f\u064a\u0629 \u0627\u0644\u0623\u0648\u0631\u0648\u0628\u064a\u0629 \u0648\u0627\u0644\u0645\u0645\u0644\u0643\u0629 \u0627\u0644\u0645\u062a\u062d\u062f\u0629 \u0648\u0633\u0648\u064a\u0633\u0631\u0627: \u062a\u0639\u062a\u0645\u062f \u0627\u0644\u0625\u0639\u0644\u0627\u0646\u0627\u062a \u0627\u0644\u0645\u062e\u0635\u0651\u0635\u0629 \u0648\u062a\u062e\u0632\u064a\u0646 \u0627\u0644\u0645\u0639\u0644\u0648\u0645\u0627\u062a \u0623\u0648 \u0642\u0631\u0627\u0621\u062a\u0647\u0627 \u0639\u0644\u0649 \u062c\u0647\u0627\u0632\u0643 \u0639\u0644\u0649 \u0645\u0648\u0627\u0641\u0642\u062a\u0643 (\u0627\u0644\u0645\u0627\u062f\u0629 6(1)(\u0623) \u0645\u0646 \u0627\u0644\u0644\u0627\u0626\u062d\u0629 \u0627\u0644\u0639\u0627\u0645\u0629 \u0644\u062d\u0645\u0627\u064a\u0629 \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a \u0648\u062a\u0648\u062c\u064a\u0647 \u0627\u0644\u062e\u0635\u0648\u0635\u064a\u0629 \u0627\u0644\u0625\u0644\u0643\u062a\u0631\u0648\u0646\u064a\u0629). \u0623\u0645\u0627 \u0627\u0644\u0625\u0639\u0644\u0627\u0646\u0627\u062a \u063a\u064a\u0631 \u0627\u0644\u0645\u062e\u0635\u0651\u0635\u0629 \u0648\u0642\u064a\u0627\u0633 \u0627\u0644\u0625\u0639\u0644\u0627\u0646\u0627\u062a \u0648\u0645\u0646\u0639 \u0627\u0644\u0627\u062d\u062a\u064a\u0627\u0644 \u0641\u062a\u0639\u062a\u0645\u062f \u0639\u0644\u0649 \u0627\u0644\u0645\u0635\u0644\u062d\u0629 \u0627\u0644\u0645\u0634\u0631\u0648\u0639\u0629 (\u0627\u0644\u0645\u0627\u062f\u0629 6(1)(\u0648)). \u062a\u064f\u062c\u0645\u0639 \u0627\u0644\u0645\u0648\u0627\u0641\u0642\u0629 \u0639\u0628\u0631 \u0623\u062f\u0627\u0629 \u0627\u0644\u0645\u0648\u0627\u0641\u0642\u0629 \u0645\u0646 Google (UMP) \u0627\u0644\u0645\u0639\u062a\u0645\u062f\u0629 \u0636\u0645\u0646 \u0625\u0637\u0627\u0631 IAB \u0644\u0644\u0634\u0641\u0627\u0641\u064a\u0629 \u0648\u0627\u0644\u0645\u0648\u0627\u0641\u0642\u0629."],t.s)
B.W0=s(["\u0645\u0648\u0627\u0641\u0642\u062a\u0643 \u0648\u062e\u064a\u0627\u0631\u0627\u062a\u0643","\u0639\u0646\u062f \u0641\u062a\u062d \u0627\u0644\u062a\u0637\u0628\u064a\u0642 \u0644\u0623\u0648\u0644 \u0645\u0631\u0629 \u0641\u064a \u0647\u0630\u0647 \u0627\u0644\u0645\u0646\u0627\u0637\u0642\u060c \u062a\u0638\u0647\u0631 \u0646\u0627\u0641\u0630\u0629 \u062a\u062a\u064a\u062d \u0644\u0643 \u0642\u0628\u0648\u0644 \u0627\u0644\u0625\u0639\u0644\u0627\u0646\u0627\u062a \u0627\u0644\u0645\u062e\u0635\u0651\u0635\u0629 \u0623\u0648 \u0631\u0641\u0636\u0647\u0627. \u064a\u0645\u0643\u0646\u0643 \u062a\u063a\u064a\u064a\u0631 \u0645\u0648\u0627\u0641\u0642\u062a\u0643 \u0623\u0648 \u0633\u062d\u0628\u0647\u0627 \u0641\u064a \u0623\u064a \u0648\u0642\u062a \u0645\u0646 \u0627\u0644\u0625\u0639\u062f\u0627\u062f\u0627\u062a \u2190 \u062e\u064a\u0627\u0631\u0627\u062a \u062e\u0635\u0648\u0635\u064a\u0629 \u0627\u0644\u0625\u0639\u0644\u0627\u0646\u0627\u062a\u060c \u0643\u0645\u0627 \u064a\u0645\u0643\u0646\u0643 \u0625\u0639\u0627\u062f\u0629 \u062a\u0639\u064a\u064a\u0646 \u0627\u0644\u0645\u0639\u0631\u0651\u0641 \u0627\u0644\u0625\u0639\u0644\u0627\u0646\u064a \u0623\u0648 \u062d\u0630\u0641\u0647 \u0645\u0646 \u0625\u0639\u062f\u0627\u062f\u0627\u062a Android. \u0631\u0641\u0636 \u0627\u0644\u0645\u0648\u0627\u0641\u0642\u0629 \u0644\u0627 \u064a\u0645\u0646\u0639\u0643 \u0645\u0646 \u0627\u0633\u062a\u0639\u0645\u0627\u0644 \u0627\u0644\u062a\u0637\u0628\u064a\u0642."],t.s)
B.Zu=s(["\u062d\u0642\u0648\u0642\u0643","\u062a\u0645\u0646\u062d\u0643 \u0627\u0644\u0644\u0627\u0626\u062d\u0629 \u0627\u0644\u0639\u0627\u0645\u0629 \u0644\u062d\u0645\u0627\u064a\u0629 \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a \u0627\u0644\u062d\u0642 \u0641\u064a \u0627\u0644\u0648\u0635\u0648\u0644 \u0625\u0644\u0649 \u0628\u064a\u0627\u0646\u0627\u062a\u0643 \u0648\u062a\u0635\u062d\u064a\u062d\u0647\u0627 \u0648\u0645\u062d\u0648\u0647\u0627 \u0648\u062a\u0642\u064a\u064a\u062f \u0645\u0639\u0627\u0644\u062c\u062a\u0647\u0627 \u0648\u0646\u0642\u0644\u0647\u0627\u060c \u0648\u0627\u0644\u0627\u0639\u062a\u0631\u0627\u0636 \u0639\u0644\u0649 \u0645\u0639\u0627\u0644\u062c\u062a\u0647\u0627\u060c \u0648\u0633\u062d\u0628 \u0645\u0648\u0627\u0641\u0642\u062a\u0643 \u0641\u064a \u0623\u064a \u0648\u0642\u062a. \u0648\u0628\u0645\u0627 \u0623\u0646\u0646\u0627 \u0644\u0627 \u0646\u062e\u0632\u0651\u0646 \u0628\u064a\u0627\u0646\u0627\u062a\u0643 \u0627\u0644\u0634\u062e\u0635\u064a\u0629\u060c \u0641\u0625\u0646 \u0627\u0644\u0637\u0644\u0628\u0627\u062a \u0627\u0644\u0645\u062a\u0639\u0644\u0642\u0629 \u0628\u0628\u064a\u0627\u0646\u0627\u062a \u0627\u0644\u0625\u0639\u0644\u0627\u0646\u0627\u062a \u062a\u0639\u0627\u0644\u062c\u0647\u0627 Google (https://myaccount.google.com/data-and-privacy)\u060c \u0648\u0633\u0646\u0633\u0627\u0639\u062f\u0643 \u0625\u0646 \u062a\u0648\u0627\u0635\u0644\u062a \u0645\u0639\u0646\u0627. \u0648\u064a\u062d\u0642 \u0644\u0643 \u0623\u064a\u0636\u0627\u064b \u062a\u0642\u062f\u064a\u0645 \u0634\u0643\u0648\u0649 \u0625\u0644\u0649 \u0647\u064a\u0626\u0629 \u062d\u0645\u0627\u064a\u0629 \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a \u0641\u064a \u0628\u0644\u062f\u0643."],t.s)
B.XT=s(["\u0646\u0642\u0644 \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a \u062f\u0648\u0644\u064a\u0627\u064b","\u0642\u062f \u062a\u0639\u0627\u0644\u062c Google \u0628\u064a\u0627\u0646\u0627\u062a \u0627\u0644\u0625\u0639\u0644\u0627\u0646\u0627\u062a \u062e\u0627\u0631\u062c \u0628\u0644\u062f\u0643\u060c \u0628\u0645\u0627 \u0641\u064a \u0630\u0644\u0643 \u0641\u064a \u0627\u0644\u0648\u0644\u0627\u064a\u0627\u062a \u0627\u0644\u0645\u062a\u062d\u062f\u0629\u060c \u0645\u0639 \u0636\u0645\u0627\u0646\u0627\u062a \u0645\u062b\u0644 \u0627\u0644\u0628\u0646\u0648\u062f \u0627\u0644\u062a\u0639\u0627\u0642\u062f\u064a\u0629 \u0627\u0644\u0642\u064a\u0627\u0633\u064a\u0629 \u0644\u0644\u0645\u0641\u0648\u0636\u064a\u0629 \u0627\u0644\u0623\u0648\u0631\u0648\u0628\u064a\u0629 \u0648\u0625\u0637\u0627\u0631 \u062e\u0635\u0648\u0635\u064a\u0629 \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a \u0628\u064a\u0646 \u0627\u0644\u0627\u062a\u062d\u0627\u062f \u0627\u0644\u0623\u0648\u0631\u0648\u0628\u064a \u0648\u0627\u0644\u0648\u0644\u0627\u064a\u0627\u062a \u0627\u0644\u0645\u062a\u062d\u062f\u0629."],t.s)
